            currentBranch = cli_execute_command({
                command: 'git rev-parse --abbrev-ref HEAD',
                workingDirectory: workingDir
            });
        } catch (e) {
            console.log('⏱️ timer: could not determine current branch, skipping:', e.toString().substring(0, 100));
