        var mergeMsg = storyKey + ' test rework: merge origin/main and resolve test conflicts';
        runInRepo('git commit -m "' + mergeMsg.replace(/"/g, '\\"') + '"', workingDir);
        console.log('✅ Committed merge with auto-resolved test conflicts');
