+        './config.js': { LABELS: {} },
+        './common/tokenUsageComment.js': {
+            postTokenUsageComments: function () {}
+        }
+    };
+    return loadModule(
+        'js/storyTestAutomationRework.js',
+        makeRequire(requireMap),
+        Object.assign({
+            cli_execute_command: function () { return ''; },
+            file_read: function () { return null; },
+            file_write: function () {}
+        }, mocks || {})
+    );
