+                return template.replace(/\{ticketKey\}/g, values.ticketKey);
+            }
+        },
+        './common/autoStart.js': {
+            triggerConfiguredWorkflowForTicket: function () { return true; },
+            triggerSmIfIdle: function () {}
+        },
