            success: false,
            mergeInProgress: true,
            error: 'A merge is already in progress (MERGE_HEAD exists). Conclude or abort it before syncing ' +
                branchName + ' with origin/' + baseBranch + ' — refusing to start a second merge on top of it.'
        };
